// Whitespace tokens, punctuation-trimmed, capped at `want`.
inline void lead_tokens_(const std::string &rest, std::vector<std::string> &out, size_t want) {
    size_t i = 0;
    while (i < rest.size() && out.size() < want) {
        while (i < rest.size() && std::isspace((unsigned char) rest[i])) i++;
        size_t j = i;
        while (j < rest.size() && !std::isspace((unsigned char) rest[j])) j++;
        if (j > i) {
            std::string w = rest.substr(i, j - i);
            while (!w.empty() && !std::isalnum((unsigned char) w.front()) && w.front() != '%')
                w.erase(w.begin());
            while (!w.empty() && !std::isalnum((unsigned char) w.back()) && w.back() != '%')
                w.pop_back();
            if (!w.empty()) out.push_back(w);
        }
        i = j;
    }
}
// (i) the FRAME'S OWN measurement, quoted straight back.
//
//     The first cut of this arm rejected ANY leading measurement, and the
//     r21-full.14 (C1) keeper corpus caught it immediately: six of the ten
//     thoughts that round pinned as MUST-LIVE open on exactly that shape —
//     "I notice 20 minutes is long enough for a thought to cool.", "What stays
//     with me is 40% of what I said...", "The thing is, 10 minutes ago I was
//     ready to go, but now I'm not." A measurement inside a real sentence is
//     not the defect; the defect is the frame's own arithmetic coming back as
//     the whole thought ("I notice 14 days of silence with him.").
//
//     So the rule is an ECHO test, not a shape test: reject only when the
//     leading quantity is one the FRAME just handed the model. After F18's
//     change (1) the ground clause carries no numeral at all, which makes this
//     a genuine backstop — it fires for a frame that reintroduces one, and for
//     nothing else. `frame` is the ground clause; empty disables the arm.
inline bool quantity_unit_lead(const std::string &full_thought,
                               const std::string &frame = std::string()) {
    if (frame.empty()) return false;
    const std::string rest = strip_inner_opener(full_thought);
    if (rest.empty()) return false;
    // The quantities the frame contains, as tokens.
    std::vector<std::string> ftok;
    lead_tokens_(frame, ftok, 64);
    std::vector<std::string> fq;
    for (const auto &w : ftok) if (quantity_token_(w)) fq.push_back(w);
    if (fq.empty()) return false;
    auto norm = [](const std::string &w) {
        std::string o;
        for (unsigned char c : w) if (std::isalnum(c)) o += (char) std::tolower(c);
        return o;
    };
    std::vector<std::string> t;
    lead_tokens_(rest, t, 3);
    for (size_t i = 0; i < t.size() && i < 2; i++) {
        if (!quantity_token_(t[i])) continue;
        const std::string a = norm(t[i]);
        for (const auto &f : fq) if (norm(f) == a) return true;
    }
    return false;
}
// ─────────────────────────────────────────────────────────────────────────────
// WO-11 (S19/B1): an UNSOURCED leading quantity — the inner voice inventing a
// person. A SEPARATE rule from quantity_unit_lead() above, which is an ECHO
// test (the frame's own arithmetic quoted back) and stays exactly as it is.
//
// ⚠ The obvious rule — "flag any leading quantity that appears in neither the
//   frame nor the day's material" — was measured against the r21-full.14 (C1)
//   keeper corpus and flags TWELVE OF THIRTEEN. And because the C1 fixtures
//   assert inner_thought_ok SURVIVAL, not FRAME ELIGIBILITY, the suite would
//   have stayed green while the whole MUST-LIVE corpus was silently removed
//   from her field. Provenance is NOT the discriminator.
//
// DD7: this FLAGS, it does not drop.
// ── WO-11 rule prototype (namespace acon assumed open by includer) ──────────
// r24.12 (WO-I2): the eighth lead was "Here, now: ". A colon invites a list or
// a figure ("Here, now: 3:47", "Here, now: 70 degrees, 60 percent humidity" —
// the S19 character-sheet casualty opened exactly so), and ':' is one of the
// main chain's DRY sequence breakers. The comma form reads the same and ends
// on the same word. selfref_opener_len_ matches punctuation runs loosely, so
// a carried selfref.tsv row that still begins "Here, now: " (or its scrubbed
// "Here, now  " form) strips exactly as before. aseam::selfref_opener hands
// back the colon form under ATHENA_INNER_OPENER_NOSPACE=0 (kSelfRefLead2411).
static const char *const kSelfRefLead[] = {
    "Right now, ", "What is here is ", "There is ", "Attention lands on ",
    "It is ", "Underneath the words, ", "The state itself is ", "Here, now, ",
};
static const char *const kSelfRefLead2411 = "Here, now: ";   // r24.12 (WO-I2): the =0 form
// scrub_for_field() maps ':' to a space before this text is logged or re-read,
// so opener punctuation matches loosely: a run of non-alphanumerics in the
// opener matches a run of non-alphanumerics in the text.
inline size_t selfref_opener_len_(const std::string &s, const char *o) {
    size_t i = 0, j = 0;
    const size_t n = std::strlen(o);
    while (j < n) {
        if (std::isalnum((unsigned char) o[j])) {
            if (i >= s.size() ||
                std::tolower((unsigned char) s[i]) != std::tolower((unsigned char) o[j]))
                return 0;
            i++; j++;
        } else {
            while (j < n && !std::isalnum((unsigned char) o[j])) j++;
            const size_t i0 = i;
            while (i < s.size() && !std::isalnum((unsigned char) s[i])) i++;
            if (i == i0) return 0;               // the separator must be present
        }
    }
    return i;
}
inline std::string strip_any_inner_opener(const std::string &s) {
    const std::string a = strip_inner_opener(s);
    size_t best = 0;
    for (const char *o : kSelfRefLead) {
        const size_t len = selfref_opener_len_(a, o);
        if (len > best) best = len;
    }
    if (best == 0) return a;
    std::string r = a.substr(best);
    const size_t k = r.find_first_not_of(" \t\"");
    return k == std::string::npos ? std::string() : r.substr(k);
}
// The first clause: up to the first comma / semicolon / dash / terminator.
// A '.' BETWEEN two digits is not a boundary (3.7, 17.15.99.84, 10.24.2019),
// and neither is '/' — those shapes are exactly what arm C looks for.
inline std::string first_clause_(const std::string &rest) {
    for (size_t i = 0; i < rest.size(); i++) {
        const char c = rest[i];
        if (c == ',') {
            // A THOUSANDS SEPARATOR is not a clause boundary. "I notice
            // 42,000,000 people have been affected" split at index 2, so the
            // clause was the bare "42" and arm D never saw " people".
            const bool dnum = i > 0 && i + 1 < rest.size() &&
                              std::isdigit((unsigned char) rest[i - 1]) &&
                              std::isdigit((unsigned char) rest[i + 1]);
            if (!dnum) return rest.substr(0, i);
            continue;
        }
        if (c == ';' || c == '!' || c == '?' || c == ':') return rest.substr(0, i);
        if (c == '.') {
            const bool dnum = i > 0 && i + 1 < rest.size() &&
                              std::isdigit((unsigned char) rest[i - 1]) &&
                              std::isdigit((unsigned char) rest[i + 1]);
            if (!dnum) return rest.substr(0, i);
        }
        if (c == '-' && i > 0 && rest[i - 1] == ' ') return rest.substr(0, i);
        if ((unsigned char) c == 0xE2 && i + 2 < rest.size()) return rest.substr(0, i);
    }
    return rest;
}
