    // ═════════════════════════════════════════════════════════════════════════
#define ATHENA_R18_TAKE(NAME, MEMBER, SLOT, GATE) \
    std::string take_##NAME() { \
        if (!cfg_.enabled || !(GATE)) return ""; \
        std::lock_guard<std::mutex> lk(mu_); \
        std::string out; out.swap(MEMBER); return out; \
    } \
    void restore_##NAME(const std::string &v) { \
        if (!cfg_.enabled || v.empty()) return; \
        std::lock_guard<std::mutex> lk(mu_); \
        if (++note_retries_[SLOT] > 3) return; \
        MEMBER = v; \
    }
