    // r24.21: one bounded pending attempt, never a heard/told record.
    // Render the original source through the established field word renderer
    // before exposing it. The existing C36 voice receipt restores a dropped
    // safe note; no duplicate, indefinitely retained raw-history field exists.
    void note_sent_unconfirmed(const std::string &text) {
        if (!cfg_.enabled || text.empty()) return;
        std::lock_guard<std::mutex> lk(mu_);
        pending_sent_words_ = clip_utf8_bytes(text, 512);
    }
    std::string take_voice_note(std::string (*source_words)(const std::string &) = nullptr) {
        if (!cfg_.enabled) return "";
        std::lock_guard<std::mutex> lk(mu_);
        std::string out;
        out.swap(voice_note_);
        if (!pending_sent_words_.empty()) {
            if (!out.empty()) out += ". ";
            out += "I sent wording to my voice, but its playback was unconfirmed. The attempted wording was ";
            if (source_quote_eligible(Source::IMAGINED, pending_sent_words_, cfg_.inner_unsourced_q)) {
                // Nested quotes cannot end the source quotation. Quoting before
                // scrub also strips embedded vocal tokens instead of activating
                // them as field gestures. The untouched original stays in the
                // diagnostic transmission record, not a canonical speech row.
                std::string quoted;
                for (char c : pending_sent_words_) {
                    if (c == '"') quoted += '\'';
                    else if (c == '=') quoted += " equals ";
                    else quoted += c;
                }
                quoted = "\"" + quoted + "\"";
                out += source_words ? source_words(quoted)
                                    : spell_number_shapes(scrub_for_field(quoted), spell_cardinal);
            } else {
                out += "a generated passage with an ungrounded quantitative detail";
            }
            pending_sent_words_.clear();
        }
        return out;
    }
