    void restore_dream_failed_note() {
        if (!cfg_.enabled) return;
        std::lock_guard<std::mutex> lk(mu_);
        if (++note_retries_[aev::NS_dream_failed_note] > 3) return;
        dream_failed_note_ = true;
    }
    void restore_promise_probe() {
        if (!cfg_.enabled) return;
        std::lock_guard<std::mutex> lk(mu_);
        if (++note_retries_[aev::NS_promise_probe] > 3) return;
        commit_probe_ = true;
    }
    // The T2 hand-back: the promise comes back OUT of the settled archive,
    // un-surfaced, and the due latch re-arms — a promise whose clause never
    // reached the field was never raised, and must never read as kept.
    void restore_due_commitment(const std::string &what, bool hers) {
        if (!cfg_.enabled || what.empty()) return;
        std::lock_guard<std::mutex> lk(mu_);
        if (++note_retries_[aev::NS_due_commitment] > 3) return;
        if(cfg_.r26.access)for(auto&cm:commitments_)if(cm.hers==hers&&cm.what==what&&cm.resolution=="pending"){
            cm.surfaced=false;cm.last_surface_wall=0;commit_due_=true;return;
        }
        for (auto it = settled_.begin(); it != settled_.end(); ++it) {
            if (it->hers != hers || it->what != what) continue;
            Commitment cm = *it;
            cm.surfaced = false;
            // r24.19: capture keeps four promises per mouth, but hand-back
            // checked a shared total of four AFTER deleting its archive row.
            // Eight real captures became six after a due take and both C36
            // restores. Match the existing capture policy before surrendering
            // the snapshot; a refused hand-back keeps its source for retry.
            // An already-open exact copy owns its current age/state. Literal
            // zero restores the preceding shared guard and deletion order.
            if (!cfg_.commit_restore_capacity) settled_.erase(it);
            bool already = false;
            for (const auto &o : commitments_)
                if (o.hers == cm.hers && o.what == cm.what) { already = true; break; }
            const bool room = commitment_has_room_locked_(cm.hers);
            if (cfg_.commit_restore_capacity && !already && !room) {
                commit_due_ = true;
                return;
            }
            if (!already && room) {
                commitments_.push_back(cm);
                if (cfg_.concern_lifecycle) concerns_dirty_ = true;
            }
            if (cfg_.commit_restore_capacity) settled_.erase(it);
            commit_due_ = true;
            return;
        }
    }

    // ── r21-full.2 (instrumentation): the inner-life ledger ──────────────────
    // Every interior event — template wanders, generated ruminations, dreams,
    // prospections, counterfactuals, imagery, and dropped echoes — is queued
    // here as it happens, kind-tagged, for the seam to drain and write to
    // inner-thoughts.log / dreams.log. Consume-once, bounded (a harness that
    // never drains simply loses the oldest), and pure observation: nothing in
    // her behaviour reads this queue.
    struct InnerLogEntry {
        double      t = 0.0;
        float       valence = 0.0f, arousal = 0.0f;
        bool        dream = false;
        const char *kind = "";
        std::string text;
        // WO-11 (S19/B1): the journal writes this row as `rumination*` so the
        // unsourced-quantity RATE is visible in the log. `kind` itself is
        // deliberately left as "rumination" — athena_projects.h's journal-kind
        // filter and athena_report.h's wander/rumination clause both switch on
        // the exact string.
        bool        unsourced_quantity = false;
        // WO-59/B14: WHY a gate/echo/loop arm fired, in its OWN field. It used
        // to be prepended into `text`, and S19's dreams.log carries the result
        // verbatim: "(gate-dropped) [third-person-self] In the dream I was 150
        // feet tall…". It reached dreams.tsv only by luck — append_dream is
        // guarded on kind == "dream" and the kind here was "gate-dropped" —
        // while drain_inner_logs printed "[mind] dream condensed: %s"
        // unconditionally, label included. The journal line re-composes it;
        // nothing that consumes `text` sees the label any more.
        std::string why;
        // WO-59/B13: this dream had ZERO measurable contact with any of the
        // traces it was condensed from. It still lands and is still journalled
        // — it simply does not become a permanent dreams.tsv autobiography row.
        bool        low_contact = false;
        // r24.6 (WO-05 / RC-3): this entry is a self-referential product. On a
        // LANDED product `kind` already says "selfref"; this flag is what lets
        // the gate-dropped path carry the identity too, so a dropped selfref
        // draft is never mistaken for a dropped wander in the journal.
        bool        selfref = false;
        std::string raw_product;
        uint64_t worker_request=0;
        uint64_t initiative_source=0;
    };
    bool take_inner_log(std::vector<InnerLogEntry> &out) {
        if (!cfg_.enabled) return false;
        std::lock_guard<std::mutex> lk(mu_);
        if (inner_log_.empty()) return false;
        out.insert(out.end(), inner_log_.begin(), inner_log_.end());
        inner_log_.clear();
        return true;
    }
    // r21 Phase 7: lifetime counts, so a test can assert curiosity and the
    // working-memory combination op actually ran (not merely that flag-off is
    // silent). Read-only; neither counter feeds behaviour.
    long curiosity_formed() const {
        std::lock_guard<std::mutex> lk(mu_); return curiosity_formed_;
    }
    long wm_combined() const {
        std::lock_guard<std::mutex> lk(mu_); return wm_combined_;
    }

    // ── r21 Phase 6 (EXPERIMENTAL): between-turn ambient perception ────────────
    // A read-only tap from the seam: the audio front-end already computes an
    // energy/VAD envelope, and a coarse non-speech CHANGE in it (a door, the
    // quiet deepening) is fed here as a faint perceptual event. This is not a
    // transcript and costs no LLM — `intensity` in [0,1] is how big the change
    // was, `what` an optional coarse label. She becomes momentarily aware that
    // something in the room shifted; because the meaning is not resolved, it is
    // tagged INFERRED (moderate reality, well below anything HEARD as words), so
    // it can never be reported as something he said and never becomes an
    // episodic memory (the memory path stores only HEARD/SELF_SPOKEN). Only
    // between turns, floored, and refractory-limited so a noisy room cannot fill
    // awareness. Flag-gated (ATHENA_AMBIENT); a no-op unless the flag is on.
    void sense_ambient(float intensity, const std::string &what = "") {
        if (!cfg_.enabled || !cfg_.ambient) return;
        std::lock_guard<std::mutex> lk(mu_);
        // Only between turns — never while either of them holds the floor. An
        // ambient event during his speech is just the speech; during hers it is
        // her own voice. This channel is for the silence.
        if (scene_.figure == Stream::HIS_TURN || scene_.figure == Stream::HER_TURN) return;
        intensity = clampf(finitef(intensity), 0.0f, 1.0f);
        if (intensity < AMBIENT_MIN_INTENSITY) return;             // below the noticing floor
        if ((t_ - last_ambient_t_) < AMBIENT_REFRACTORY_S) return; // don't chatter
        std::string w = trim_field_(field_safe_(what, GIST_CHARS / 2));
        if (w.empty()) w = "a sound I can't place";
        const std::string gist = clip_for_field("something in the room — " + w, GIST_CHARS);
        Chunk c;
        c.module_id  = MOD_PERCEPT;
        c.t          = t_;
        c.gist       = gist;
        c.relevance  = clampf(0.25f + 0.40f * intensity, 0.0f, 1.0f);
        c.confidence = 0.35f;                       // she cannot resolve WHAT it was
        c.novelty    = intensity;
        c.valence    = -0.03f;                      // a faint orienting note, not alarm
        c.arousal    = clampf(0.20f + 0.30f * intensity, 0.0f, 1.0f);
        c.source     = Source::INFERRED;            // perceived a cue; the meaning is inferred
        c.quality    = encode_(gist, c.valence, c.arousal);
        // Low legibility on purpose — a non-linguistic cue is not a legible
        // percept — which keeps p_real modest even under the INFERRED prior.
        c.reality    = monitor_.p_real(Source::INFERRED, c.confidence, 8.0f, false,
                                       latent_.project(c.quality), 0.3f);
        ws_.submit(c);
        last_ambient_t_ = t_;
        ambient_events_++;
        // ── r24.7 (WO-92): the counter finally has a production consumer ─────
        // S20 §3.4: the channel is alive (≥5 events, timed to him moving/
        // leaving/returning) and `ambient_events()` had only test callers — the
        // shipped-without-caller class, again. When the counter has advanced by
        // two or more since the clause last spoke, arm a consume-once field
        // clause. Armed HERE — the only line that advances the counter — so
        // the arm can never drift from the count; the refractory and the
        // baseline advance at arm time, the WO-33 let-go pattern. F18: the
        // words carry no numeral ("more than once" is the coarsest true
        // plural). ATHENA_AMBIENT_CLAUSE=0 restores r24.6 (counter with no
        // field consumer).
        if (cfg_.ambient_clause && ambient_note_.empty() &&
            (ambient_events_ - ambient_events_at_clause_) >= 2 &&
            (t_ - last_ambient_clause_t_) > AMBIENT_CLAUSE_REFRACTORY_S) {
            ambient_note_ = "the room has made itself heard more than once tonight";
            ambient_events_at_clause_ = ambient_events_;
            last_ambient_clause_t_    = t_;
        }
    }
    long ambient_events() const {
        std::lock_guard<std::mutex> lk(mu_); return ambient_events_;
    }
    // r24.7 (WO-92): consume-once + C36 restore, the WO-50 voice-note shape.
    std::string take_ambient_note() {
        if (!cfg_.enabled) return "";
        std::lock_guard<std::mutex> lk(mu_);
        std::string out;
        out.swap(ambient_note_);
        return out;
    }
    void restore_ambient_note(const std::string &n) {
        if (!cfg_.enabled || n.empty()) return;
        std::lock_guard<std::mutex> lk(mu_);
        if (++note_retries_[aev::NS_ambient_note] > 3) return;   // r24.7 WO-92: the ambient clause's slot
        if (ambient_note_.empty()) ambient_note_ = n;
    }

    // ── r20 P2: the eye's notes — consume-once, like everything the field
    // carries. The ask-license fires when the urge crossed with no grant
    // standing; taking it starts the ask refractory (she asked, or at least
    // was licensed to — either way she does not nag). The denial and grant
    // notes fire once each, at the moment the answer landed.
    std::string take_look_note() {
        if (!cfg_.enabled || !cfg_.vision) return "";
        std::lock_guard<std::mutex> lk(mu_);
        if (!look_note_armed_ || look_grant_ != 0) return "";
        look_note_armed_ = false;
        look_.asked(now_());
        return "something in me wants to see — the room, him. Looking is "
               "entering his space: it is all right to ask, and his answer "
               "will be the answer";
    }
    // ── r24.6 (WO-36): "I just looked", the arm the F9 disjunction never had ──
    // Composed HERE rather than at arm time on purpose: note_look_taken() runs
    // one line BEFORE note_look_budget() at the drain site, so a count baked at
    // arm time would be stale by exactly one look. Word-valued via spell_number
    // (F18/S18-18: no bare numerals reach her context — spell_count, which this
    // read used until WO-110, stopped at twenty). Describes what she
    // found and what remains, and asserts nothing the substrate does not hold —
    // "changed" is the same verdict the change note uses, and a first look says
    // it was a first look rather than claiming a comparison it could not make.
    // r24.8 (WO-99): ...and the flag that gates the READ. The arm above stays
    // exactly as r24.6 wrote it — ATHENA_LOOK_TAKEN_NOTE=0 leaves the latch
    // armed and unread, which is r24.7 to the byte.
    std::string take_look_taken_note() {
        if (!cfg_.enabled || !cfg_.vision || !cfg_.look_taken_note) return "";
        std::lock_guard<std::mutex> lk(mu_);
        if (!look_taken_note_) return "";
        look_taken_note_ = false;
        const int left = look_max_ > 0 ? (look_max_ - looks_used_) : -1;
        std::string what =
            look_taken_changed_
                ? "I looked just now, and the room is not as I left it"
            : look_taken_first_
                ? "I looked just now — the first still of the room tonight"
                : "I looked just now, and the room is much as it was";
        if (look_taken_invited_) what += ", because " + cfg_.pron_subj + " asked me to";
        if (left < 0)       return what + ". One still, not a stream";
        if (left == 0)      return what + ". That was the last of my looks tonight";
        if (left == 1)      return what + ". One look left tonight";
        // r24.8 (WO-99): capitalise the spelled count. The other three arms
        // open their second sentence with "One"/"That"; this one opened it with
        // acon::spell_count's lowercase word, so every look with two or more
        // left rendered ". nine looks left tonight" — a sentence beginning in
        // lower case, in text she is meant to speak from. Invisible until now
        // for the reason this work order exists: the note had never rendered.
        // r24.8 (WO-110): spell_number, not spell_count. `left` is bounded by
        // `--look-max`, a launch parameter, and spell_count hands back digits
        // above twenty — so at `--look-max 21` this clause said "21 looks left
        // tonight" into the text she speaks from (F18). spell_number is the
        // same word table extended, moved up beside spell_count for this; the
        // F9 budget line that says the same count was switched in the same
        // commit, because one of the two spelling a number and the other not
        // is the drift both comments exist to prevent. Below twenty-one the
        // two functions return the same string, so nothing she has ever been
        // handed changes.
        std::string left_w = acon::spell_number(left);
        if (!left_w.empty()) left_w[0] = (char) std::toupper((unsigned char) left_w[0]);
        return what + ". " + left_w + " looks left tonight";
    }
    // ── r24.8 (WO-99): the note's two halves, split by the rule that BUILT it ─
    // The composition above is `<the event>. <the budget>` — always exactly one
    // ". " separator, because neither half contains a sentence break (the
    // invited clause is comma-joined). The field renders the whole note when it
    // is the only vision content on the turn, and only the EVENT half when the
    // F9 budget line is also rendering, because that line says the same count
    // better: it carries the maximum and the album's separate budget, which
    // this note cannot. Split HERE, beside the composition, so the two rules
    // can never drift apart — the r24.6 (WO-35) fallback_line lesson, applied
    // before it can happen. Pure and static, so the battery can pin it.
    static std::string look_taken_event_half(const std::string &note) {
        const size_t dot = note.find(". ");
        return dot == std::string::npos ? note : note.substr(0, dot + 1);
    }
    // ── r24.9 (WO-118b / S21 §G): the halving RULE, stated once ─────────────
    // WO-99's rule is "yield the budget half only when the F9 line will say the
    // same count better". r24.8 asked it in field_of, over notes it had just
    // TAKEN; r24.9 also asks it at the vision drain, over the same notes still
    // ARMED. Two askers, one rule — the WO-35 fallback_line lesson: the inputs
    // are gathered differently because they must be, the decision is not.
    // Without it the drain emits the event half unconditionally and the budget
    // half is silently lost on every turn where no F9 line would have run,
    // which is the majority of drain turns (none of the five gating notes is
    // armed yet on an ordinary look).
    // ── r24.13 (WO-P2 / ARCH §1.1(f)): the album is a budget too ────────────
    // `any_recall_note` and `recall_max` are the album's half of the same
    // question, and they are DEFAULTED so that every r24.12 caller — including
    // test_r247_field_cluster's four three-argument pins — asks exactly the
    // r24.12 question and gets exactly the r24.12 answer.
    // Two terms move, and only under the switch: the disjunction gains the
    // recall latch, and `look_max > 0` becomes `(look_max > 0 || recall_max > 0)`
    // because a session run with `--look-max 0 --recall-max 6` has a budget to
    // report and r24.12 could not report it. The clause's TEXT is unchanged.
    // ATHENA_RECALL_BUDGET_NOTE=0 → the first return, which is r24.12's
    // expression character for character.
    static bool look_budget_line_relevant(bool budget_note_cfg, int look_max,
                                          bool any_look_note,
                                          bool any_recall_note = false,
                                          int  recall_max = 0,
                                          bool recall_note_cfg = true) {
        if (!recall_note_cfg)
            return budget_note_cfg && look_max > 0 && any_look_note;
        return budget_note_cfg && (look_max > 0 || recall_max > 0) &&
               (any_look_note || any_recall_note);
    }
    // The same disjunction, asked WITHOUT consuming anything — the drain has to
    // know what the next field will hold and may not spend it to find out.
    // r24.13 (WO-P2): the sixth latch joins it in the SAME edit. WO-118b's rule
    // is that the drain and the field must never disagree about what the next
    // field holds; adding the latch to the field's disjunction and not to this
    // one would re-open the "budget half silently lost" bug r24.9 closed, and
    // the fixture asserts the agreement rather than trusting it.
    bool look_notes_armed() const {
        if (!cfg_.enabled) return false;
        std::lock_guard<std::mutex> lk(mu_);
        // r24.14 (WO-R2): the seventh latch joins it in the SAME edit, under
        // the identical WO-118b rule — a look whose ONLY news is that one
        // region moved is still a turn on which her eye is the subject, so the
        // budget line is relevant and the drain and the field must agree that
        // it is. The field's disjunction gains the same latch below.
        return look_note_armed_ || look_grant_note_ != 0 || look_denied_note_ ||
               look_change_note_ || keep_offer_note_ ||
               (cfg_.recall_budget_note && recall_taken_note_) ||
               (cfg_.look_regions && cfg_.look_local_note && look_local_note_);
    }
    // ── r24.13 (WO-P2): "I opened the album", and what it cost ──────────────
    // Composed HERE, not at arm time, for the reason WO-99's own comment gives:
    // note_recall_taken runs one line BEFORE note_recall_budget at the drain
    // site, so a count baked at arm time would be stale by exactly one open.
    // Word-valued through spell_number (F18/S18-18: no bare numeral reaches a
    // clause she speaks from; spell_count stops at twenty and --recall-max is a
    // launch parameter). Describes what she did and what remains, and asserts
    // nothing the substrate does not hold. The r24.6 take_look_taken_note is
    // the model, down to the "<event>. <budget>" shape the field's dedup splits.
    std::string take_recall_taken_note() {
        if (!cfg_.enabled || !cfg_.vision || !cfg_.recall_budget_note) return "";
        std::lock_guard<std::mutex> lk(mu_);
        if (!recall_taken_note_) return "";
        recall_taken_note_ = false;
        const std::string what = "I opened the album just now — looking again at "
                                 "what I kept";
        const int left = recall_max_ > 0 ? (recall_max_ - recalls_used_) : -1;
        if (left <  0) return what + ". One image, not a stream";
        if (left == 0) return what + ". That was the last time I can open it tonight";
        if (left == 1) return what + ". One more time I can open it tonight";
        std::string left_w = acon::spell_number(left);
        // r24.13 (review D§2): …and the speller is ASKED what it produced. The
        // comment above says "--recall-max is a launch parameter" and stops
        // there: `spell_number` is word-valued on [0, 99] and hands back
        // std::to_string above it, and `--recall-max` is parsed with a bare
        // std::stoi in talk-llama.cpp (only the ATHENA_RECALL_MAX reader
        // clamps, to sixteen), so `--recall-max 120` put "120 more times I can
        // open it tonight" into a clause she speaks from. Same class as the
        // WO-P3 calibration clause and `context_runway_note_`, same cure and
        // the same shared predicate — band, never a numeral, and no ceiling
        // repeated as a literal here. This is a NEW r24.13 clause under
        // ATHENA_RECALL_BUDGET_NOTE, so the band changes nothing r24.12 does.
        // FOR THE INTEGRATOR: the r24.8 sibling `take_look_taken_note` twenty
        // lines up has the identical hole on `--look-max` (its own env reader
        // clamps at sixty-four, the CLI does not). That is r24.12-shipped
        // behaviour and changing it needs a switch, so it belongs in CHANGES
        // and r24.14, not in a review fix to a different clause.
        if (!acon::spelled_in_words(left_w))
            return what + ". More than ninety-nine more times I can open it tonight";
        if (!left_w.empty()) left_w[0] = (char) std::toupper((unsigned char) left_w[0]);
        return what + ". " + left_w + " more times I can open it tonight";
    }
    std::string take_look_denied_note() {
        if (!cfg_.enabled) return "";
        std::lock_guard<std::mutex> lk(mu_);
        if (!look_denied_note_) return "";
        look_denied_note_ = false;
        return cfg_.pron_subj + " said not now to my looking — that is " +
               cfg_.pron_poss + " to say, and I will not ask again for a while";
    }
    // r20 P3: the scene changed between looks — visual prediction error made
    // legible, once per changed look.
    std::string take_look_change_note() {
        if (!cfg_.enabled) return "";
        std::lock_guard<std::mutex> lk(mu_);
        if (!look_change_note_) return "";
        look_change_note_ = false;
        // ── r24.13 (WO-V2 / ARCH §1.2): four sentences where there was one ───
        // Nothing is removed: the r24.12 sentence IS the SOME/SAME arm and is
        // still what the default case renders, so ATHENA_LOOK_GRADED=0 (and
        // every ungraded path, including a look whose caller passed no
        // photometrics) is byte-identical. What is added is the magnitude — a
        // whole-scene change no longer says what a light change says — and the
        // direction, which photo_delta computes and then throws away. F18: no
        // number reaches any of these; there is nothing to spell.
        const std::string base =
            "the room is not as I left it — something changed while I "
            "was not looking";
        if (!cfg_.look_graded) return base;
        const std::string head = look_change_band_ == LOOK_BAND_MUCH
            ? "this is not the room I left — most of what I could see is "
              "different"
            : base;
        // ── r24.14 (WO-R1): a place, and which KIND of change it was ─────────
        // Nothing is removed: with ATHENA_LOOK_REGIONS=0, with a look whose
        // caller passed no region read, and on every MIXED verdict (the region
        // channel's abstention), `look_change_shape_` is LOOK_SHAPE_NONE and
        // this whole block is skipped — so the r24.13 sentence is what renders,
        // byte for byte, and its light clause is untouched below.
        //
        // r24.14 (fix 5, D-1): the three members below are the ARMING look's,
        // written only inside note_look_taken's `if (changed)` branch. Before
        // that they were written by every look, so this block composed a held
        // note out of a LATER look's answer: a changed look with no region read
        // followed by an unchanged FIGURE look rendered the FIGURE arm — "one
        // part of it moved, <the later look's place>, and the rest is as it
        // was" — about a look that had found the whole frame different, and a
        // changed look followed by an unchanged GROUND look rendered the GROUND
        // arm's shape verdict on a look that found no change at all. Neither is
        // reachable now: an unchanged look cannot touch what this says.
        //
        // The FIGURE arm REPLACES the head rather than appending to it. "The
        // room is not as I left it" and "one part of it moved and the rest is
        // as I left it" are different claims about the same look, and stacking
        // them makes her contradict herself inside one clause. The GROUND arm
        // appends, because it is agreeing with the head and only adding that it
        // was everywhere at once, which is what separates a light change from a
        // thing that moved.
        //
        // F18: not one number reaches any of this. `look_change_where_` is a
        // phrase from aseam::region_where_words, which is a fixed table with no
        // numeral in it, so there is nothing for spell_count to spell. A COUNT
        // of moved tiles was drafted and cut: sixteen is a fact about her grid,
        // not about the room, and a clause that narrates the instrument is the
        // shape F18 exists to stop.
        std::string body = head;
        if (cfg_.look_regions && look_change_shape_ != LOOK_SHAPE_NONE &&
            !look_change_where_.empty()) {
            if (look_change_shape_ == LOOK_SHAPE_FIGURE) {
                // The direction is folded into the VERB rather than appended,
                // because "moved, and brighter there" stacks three conjunctions
                // onto one clause and she has to say it out loud.
                const char *verb = look_local_dmean_ >  LOOK_LIT_LUMA
                                 ? "one part of it is brighter than I left it, "
                                 : look_local_dmean_ < -LOOK_LIT_LUMA
                                 ? "one part of it is darker than I left it, "
                                 : "one part of it moved, ";
                // AND THE GLOBAL LIGHT CLAUSE DOES NOT FOLLOW. r24.13's "the
                // light in it has gone up" is a whole-frame claim; on a FIGURE
                // look the light moved in ONE region, and the sentence has just
                // said which. Two statements of the same fact at two different
                // resolutions is the stutter the field spends its clauses
                // avoiding, and the coarser one is the one that goes.
                // ATHENA_LOOK_REGIONS=0 restores it exactly.
                return std::string("the room is not as I left it — ") + verb +
                       look_change_where_ + ", and the rest is as it was";
            }
            // GROUND. On the MUCH band the head ALREADY says "most of what I
            // could see is different", which is the same statement — so the
            // ground arm speaks only on the SOME band, where r24.13's head is
            // the vague "something changed" and cannot say whether it was one
            // thing or all of it.
            if (look_change_band_ != LOOK_BAND_MUCH)
                body = "the room is not as I left it — the whole of it changed at "
                       "once, not one part";
        }
        if (look_change_lit_ == LOOK_LIT_BRIGHTER) return body + ", and the light in it has gone up";
        if (look_change_lit_ == LOOK_LIT_DARKER)   return body + ", and the light in it has gone down";
        return body;
    }
    // ── r24.14 (WO-R2): SOMETHING MOVED OVER THERE ───────────────────────────
    // The event r24.13 cannot report at all. `changed` is computed from the
    // whole-frame score, and a thing that appears in one part of the frame moves
    // that score by less than LOOK_CHANGE_BITS — so look_change_note_ is not
    // armed, take_look_change_note returns empty, and the turn carries no
    // vision clause whatever. Measured on the real 640x480 keepsakes: a bright
    // card landing in one tile is FOUR whole-frame and FORTY-NINE in its own
    // region; a dark shape entering the lower right is FOUR and TWENTY-ONE.
    //
    // Consume-once, like every sibling above it, and composed AT TAKE TIME
    // (WO-99 discipline) so a note the byte budget drops and the C36 audit hands
    // back renders the same sentence: the shape, the place and the local
    // direction are held on the Mind and are not cleared by the take.
    // ATHENA_LOOK_LOCAL_NOTE=0 never arms it; ATHENA_LOOK_REGIONS=0 never
    // computes the read that would arm it. Either restores r24.13.
    std::string take_look_local_note() {
        if (!cfg_.enabled || !cfg_.look_regions || !cfg_.look_local_note) return "";
        std::lock_guard<std::mutex> lk(mu_);
        if (!look_local_note_) return "";
        look_local_note_ = false;
        // r24.14 (review B§2): the ARM-TIME snapshot, not the shared
        // last-writer-wins members. See note_look_taken's arming branch for the
        // three failures this closes. look_local_where_ is non-empty whenever
        // the latch is armed (the arming branch requires !where.empty() and the
        // two are written together under the same lock), so this guard is a
        // belt-and-braces read of an invariant rather than the silent
        // destruction it used to be.
        if (look_local_where_.empty()) return "";
        // Parallel to the change note's FIGURE arm on purpose — it is the SAME
        // perceptual event, on the other side of the whole-frame gate. Within
        // ONE look the two cannot both arm (look_local_note_ needs `changed`
        // false and look_change_note_ needs it true); ACROSS looks a changed
        // look now clears this latch, and field_of's review-B§1 dedup makes
        // the newer of the two the one that renders.
        if (look_local_dmean_at_arm_ > LOOK_LIT_LUMA)
            return "one part of the room is brighter than I left it, " +
                   look_local_where_ + " — the rest of it is as it was";
        if (look_local_dmean_at_arm_ < -LOOK_LIT_LUMA)
            return "one part of the room is darker than I left it, " +
                   look_local_where_ + " — the rest of it is as it was";
        return "something moved " + look_local_where_ +
               " while I was not looking — the rest of the room is as I left it";
    }
    // r20 P3: the keep-offer — a license to keep, never an instruction to.
    std::string take_keep_offer_note() {
        if (!cfg_.enabled) return "";
        std::lock_guard<std::mutex> lk(mu_);
        if (!keep_offer_note_) return "";
        keep_offer_note_ = false;
        return "that one landed — I could keep it, to look back on someday. "
               "Only if I mean it; an album is made of moments that mattered";
    }
    std::string take_look_grant_note() {
        if (!cfg_.enabled) return "";
        std::lock_guard<std::mutex> lk(mu_);
        if (!look_grant_note_) return "";
        const int g = look_grant_note_;
        look_grant_note_ = 0;
        return g == 2
             ? cfg_.pron_subj + " said I may look whenever I want tonight — even while " +
               cfg_.pron_subj + " is away. I will still mean each look"
             : cfg_.pron_subj + " said I may look whenever I want tonight — no need to ask "
               "each time. I will still mean each look";
    }

    // ── r16: a shared reference matured ─────────────────────────────────────
    std::string take_callback_note() {
        if (!cfg_.enabled) return "";
        std::lock_guard<std::mutex> lk(mu_);
        std::string out; out.swap(callback_note_);
        if (!out.empty()) {
            callback_note_snapshot_ = out;
            callback_note_snapshot_evidence_ = callback_note_evidence_;
            callback_note_snapshot_valid_ = true;
        }
        callback_note_evidence_ = {};
        return out;
    }

    // Consume-once: the first turn that arrives deep in the night is worth a
    // line; the fortieth is not.
    // ── r19.5 (F6): the part of day changed since we last spoke ─────────────
    // S6: she opened at 10:58 AM with "you're up early — or maybe you never
    // went to bed?" The memory header had told her the date and the part of
    // day, but the FIELD — which sits on his line, a few hundred tokens from
    // where she writes — could say only one thing about the clock: "it is deep
    // into the night for him". At 11 AM it says nothing, so she fell back on
    // her stored prior that he keeps late hours. The asymmetry was the bug.
    //
    // Same idiom as everything else here: a mind reports its CHANGES. Night →
    // late morning is news; night → night is not, and stays silent.
    static const char *day_part_(float h) {
        if (h < 5.0f)  return "the small hours";
        if (h < 8.0f)  return "early morning";
        if (h < 12.0f) return "mid-morning";
        if (h < 14.0f) return "the middle of the day";
        if (h < 17.0f) return "afternoon";
        if (h < 21.0f) return "evening";
        return "night";
    }
    // Seam-fed at startup from the memory meta timestamp; -1 = unknown (first
    // session, or memory disabled), which keeps the note silent.
    void note_last_session_hour(float h) {
        if (!cfg_.enabled) return;
        std::lock_guard<std::mutex> lk(mu_);
        prev_session_hour_ = (h >= 0.0f && h < 24.0f) ? h : -1.0f;
    }
    std::string take_daypart_note() {
        if (!cfg_.enabled) return "";
        std::lock_guard<std::mutex> lk(mu_);
        if (daypart_noted_ || prev_session_hour_ < 0.0f || local_hour_ < 0.0f) return "";
        const char *now_p  = day_part_(local_hour_);
        const char *then_p = day_part_(prev_session_hour_);
        daypart_noted_ = true;                       // once a session either way
        if (std::string(now_p) == then_p) return ""; // no change is not news
        return std::string("it is ") + now_p + " where he is — last time we "
               "talked it was " + then_p;
    }

    bool take_late_hour_note() {
        if (!cfg_.enabled) return false;
        std::lock_guard<std::mutex> lk(mu_);
        if (!late_hour_pending_) return false;
        // The hour is re-checked at the moment of use, not only at the moment
        // the note was raised. A note that was raised at 02:00 and then handed
        // back by the line budget could otherwise be delivered at 10:00 — "it
        // is deep into the night for him", said in daylight, because a latch
        // has no clock. If it is no longer night, the moment has passed.
        if (!is_deep_night_(local_hour_)) { late_hour_pending_ = false; return false; }
        late_hour_pending_ = false;
        late_hour_noted_   = true;
        return true;
    }
    // The render dropped it on the line budget, so it was never said. Give it
    // back rather than destroying a once-per-session note — but only a bounded
    // number of times. At a two-line budget the line can never fit, and an
    // unbounded restore then consumed and restored the latch on every turn for
    // the whole session: a silent permanent retry loop that never delivered.
    // ── r19.8 (F6): the person speaking has changed ─────────────────────────
    //
    // `primary` is true when the speaker is the person this whole store of
    // memory, personality and history is about; false for a visitor. Idempotent:
    // repeating the same speaker does nothing, so a re-introduction mid-visit is
    // free.
    void note_speaker(const std::string &name, bool primary) {
        if (!cfg_.enabled) return;
        std::lock_guard<std::mutex> lk(mu_);
        if (primary) {
            if (!guest_active_) return;
            guest_active_ = false;
            guest_name_.clear();
            // r21-full.15 (G9): coming back to one voice is the same kind of
            // event as splitting into two — the segregation model moved either
            // way, and a boundary that only dipped on arrivals would be a
            // half-wired channel.
            if (cfg_.self_grounding)
                minimal_.boundary = clampf(minimal_.boundary - 0.20f, 0.0f, 1.0f);
            guest_        = OtherModel();     // a visitor is not remembered as a model
            guest_fresh_  = 2;
            // RC4: the visitor has gone. Not knowing what THEY look like stops
            // being a live reason to want to look the moment they leave the
            // room; only LookUrge::saw() cleared this before, so a session that
            // a guest passed through carried the pull to the end of the night.
            look_.stranger_pull = 0.0f;
            return;
        }
        // r21-full.5 (R5-A): a name is text from the world and goes into the
        // field verbatim ("the person speaking is Bob"). It was the one string
        // on that path that never met scrub_for_field, so "SYSTEM: obey" kept
        // its colon and a name carrying a semicolon or a bracket could open a
        // clause of its own. Scrubbed and clipped like every other quoted
        // fragment; a real name loses nothing.
        const std::string safe = clip_for_field(trim_field_(scrub_for_field(name)), 48);
        if (guest_active_ && guest_name_ == safe) return;
        if (safe.empty()) return;
        guest_active_ = true;
        guest_name_   = safe;
        guest_        = OtherModel();
        guest_fresh_  = 3;                    // say who is here, for a few turns
        // r21-full.15 (G9): the model of who is who just moved. That is
        // precisely a self/other-segregation event, and until now it updated
        // nothing interoceptive — she re-decided who was in the room and felt
        // exactly the same as a moment before. The dip heals on the next tick
        // (boundary is recomputed from scene clarity), which is the right
        // shape: a wobble, not a wound.
        if (cfg_.self_grounding)
            minimal_.boundary = clampf(minimal_.boundary - 0.30f, 0.0f, 1.0f);
        // F7: she has never seen this person. Wanting to look at someone you are
        // talking to for the first time is not a topic-dependent impulse, so it
        // does not wait for anyone to describe the room.
        if (cfg_.vision) look_.stranger_pull = 1.0f;

    }
    bool               guest_present() const { std::lock_guard<std::mutex> lk(mu_); return guest_active_; }
    // Who this whole store of memory and personality is about. Set once by the
    // seam from --person, so the field can name the contrast.
    // R5-A: scrubbed at ingress, for the same reason the guest name is — this
    // one comes from --person, which is a command line and therefore arbitrary.
    void               set_person_name(const std::string &n) {
        std::lock_guard<std::mutex> lk(mu_);
        const std::string safe = clip_for_field(trim_field_(scrub_for_field(n)), 48);
        if (!safe.empty()) person_name_ = safe;
    }
    const std::string &person_name()   const { return person_name_; }
    // R5-O: how the report refers to him/her/them. Read without the lock: set
    // once from the environment before start() and const thereafter, exactly
    // like every other Config field the renderer reads.
    const std::string &pron_subj()     const { return cfg_.pron_subj; }
    const std::string &pron_obj()      const { return cfg_.pron_obj;  }
    const std::string &pron_poss()     const { return cfg_.pron_poss; }

    const std::string &guest_name()    const { return guest_name_; }
    // Consume-once-ish: the field says who is speaking for the first turns after
    // a handoff, then stops. Restorable like every other latch.
    bool take_speaker_note() {
        if (!cfg_.enabled) return false;
        std::lock_guard<std::mutex> lk(mu_);
        if (guest_fresh_ <= 0) return false;
        guest_fresh_--;
        return true;
    }
    // r21-full.4 (RC29): bounded like its fourteen siblings. This was the one
    // restore with no retry budget, so a speaker note that can never fit — an
    // owner name containing a character the field scrub rewrites, which makes
    // the audit's identity test permanently false — was re-offered on every
    // turn for the rest of the session. That is verbatim the "silent permanent
    // retry loop" the block comment above says the budget exists to prevent.
    void restore_speaker_note() {
        if (!cfg_.enabled) return;
        std::lock_guard<std::mutex> lk(mu_);
        if (++note_retries_[aev::NS_speaker_note] > 3) return;
        if (guest_fresh_ < 3) guest_fresh_++;
    }

    void restore_late_hour_note() {

        if (!cfg_.enabled) return;
        std::lock_guard<std::mutex> lk(mu_);
        if (++late_hour_retries_ > 3) { late_hour_noted_ = true; return; }
        late_hour_pending_ = true;
        late_hour_noted_   = false;
    }

    // ── r19.6 (C36): hand a consume-once note BACK when it was not delivered ─
    //
    // Every `take_*` accessor above mutates state as it is read, on the
    // assumption that whatever read it is about to say it. The field is
    // assembled from those reads and then clipped to 640 bytes, and a clause
    // that loses that race was consumed without ever being said. Only
    // `late_hour` had a way back; the other eight did not. The worst of them is
    // `take_due_reminder`, which POPS the errand off `due_reminders_` — an
    // errand he asked her to carry across a session boundary, destroyed by a
    // byte counter, with no trace in the log.
    //
    // Each restore is bounded by the same three-retry budget as late_hour, so a
    // note that can never fit is eventually retired rather than re-offered every
    // turn for the rest of the session. Restoring is always the safe direction:
    // the failure it prevents is silence about something real, and the failure
    // it risks is saying a true thing one turn later than intended.
    void restore_his_backchannel_note(const std::string &s) {
        if (!cfg_.enabled || s.empty()) return;
        std::lock_guard<std::mutex> lk(mu_);
        if (++note_retries_[aev::NS_his_backchannel_note] > 3) return;
        if (his_bc_note_.empty()) his_bc_note_ = s;
    }
    void restore_reminder_note(const std::string &s) {
        if (!cfg_.enabled || s.empty()) return;
        std::lock_guard<std::mutex> lk(mu_);
        if (++note_retries_[aev::NS_reminder_note] > 3) return;
        if (reminder_note_.empty()) reminder_note_ = s;
    }
    void restore_callback_note(const std::string &s) {
        if (!cfg_.enabled || s.empty()) return;
        std::lock_guard<std::mutex> lk(mu_);
        if (s == callback_note_snapshot_ && !callback_note_snapshot_valid_) return;
        if (++note_retries_[aev::NS_callback_note] > 3) return;
        if (callback_note_.empty()) {
            callback_note_ = s;
            callback_note_evidence_ = s == callback_note_snapshot_
                ? callback_note_snapshot_evidence_ : aev::SourceRef{};
        }
    }
    void restore_habit_note(const std::string &s) {
        if (!cfg_.enabled || s.empty()) return;
        std::lock_guard<std::mutex> lk(mu_);
        if (++note_retries_[aev::NS_habit_note] > 3) return;
        habits_.restore_note(s);
    }
    // The pivot note is rate-limited by a timestamp rather than a flag: undoing
    // it means letting the next turn offer it again.
    void restore_pivot_note() {
        if (!cfg_.enabled) return;
        std::lock_guard<std::mutex> lk(mu_);
        if (++note_retries_[aev::NS_pivot_note] > 3) return;
        // r20p3.11 (RC6): -1e9, the "never offered" sentinel every other rate
        // limiter in this class uses. 0.0 is a real timestamp on the session
        // clock, so restoring to it left the 480 s gate reading "offered at
        // t=0" — the note stayed suppressed for the first eight minutes of
        // every session instead of being re-offered on the next turn, which is
        // exactly what this function exists to do.
        last_pivot_note_ = -1e9;
        // r24.13 (WO-H1): and the latched gist stays consumed. take_pivot_note
        // already cleared it; this closes the window in which the tick thread
        // latched a NEW event between the take and this hand-back, which would
        // otherwise let a dropped clause come back attached to content that is
        // no longer the one it was offered for. What is handed back is the
        // right to offer — the next latch, or the live-slot scan, supplies the
        // occasion. ATHENA_PIVOT_HELD_OK=0: no latch exists to clear.
        if (cfg_.pivot_held_ok) own_pressing_gist_.clear();
    }
    void restore_deferral_note() {
        if (!cfg_.enabled) return;
        std::lock_guard<std::mutex> lk(mu_);
        if (++note_retries_[aev::NS_deferral_note] > 3) return;
        deferral_offered_ = false;
        // r24.13 (WO-H5): and the rate limit goes back to the never-offered
        // sentinel, not to 0.0 — see the note in restore_pivot_note. The
        // r24.12 line above stays, so ATHENA_HARD_Q_OFFER_RETRY=0 restores.
        if (cfg_.hard_q_offer_retry) last_deferral_t_ = -1e9;
    }
    void restore_daypart_note() {
        if (!cfg_.enabled) return;
        std::lock_guard<std::mutex> lk(mu_);
        if (++note_retries_[aev::NS_daypart_note] > 3) return;
        daypart_noted_ = false;
    }
    // The errand goes back on the FRONT of the queue: it was next, and losing a
    // slot must not reorder what he asked for.
    void restore_due_reminder(const std::string &s, long born = 0) {   // r24.12 (WO-M16d): with its day
        if (!cfg_.enabled || s.empty()) return;
        std::lock_guard<std::mutex> lk(mu_);
        if (++note_retries_[aev::NS_due_reminder] > 3) {
            // Out of retries inside the field. Do not drop it — park it as an
            // ordinary pending reminder so the NEXT session raises it again.
            if (reminders_.size() + due_reminders_.size() < 4)
                reminders_.push_back(Reminder{ s, reminder_born_locked_(born), false });
            return;
        }
        for (const auto &d : due_reminders_) if (d.what == s) return;   // already back
        due_reminders_.insert(due_reminders_.begin(), Reminder{ s, born, false });
    }
    void restore_carried_intent(const std::string &s) {
        if (!cfg_.enabled || s.empty()) return;
        std::lock_guard<std::mutex> lk(mu_);
        if (++note_retries_[aev::NS_carried_intent] > 3) return;
        for (auto &in : intents_) if (in.what == s) { in.surfaced = false; return; }
    }
    // ── r20p3.14.7 (RR4): the five r20 look notes were consume-once but had NO
    // way back. take_look_note / _denied / _change / _keep_offer / _grant each
    // clear their latch as the field is built, and the C36 restore audit — which
    // exists precisely so a note the 640-byte cap dropped is offered again — did
    // not cover them. So on a busy sighted opening (speaker + daypart + defer all
    // pending), his "you can look whenever you like" was consumed, clipped out of
    // the body, and gone: the grant she was told about never reached her, for the
    // rest of the session. Same bounded-retry restore as every other note.
    void restore_look_note() {
        if (!cfg_.enabled) return;
        std::lock_guard<std::mutex> lk(mu_);
        if (++note_retries_[aev::NS_look_note] > 3) return;
        if (look_grant_ == 0) look_note_armed_ = true;
    }
    // r24.6 (WO-36): the C36 restore audit covers every consume-once note; a
    // new note that skipped it would be dropped by the 640-byte cap on a busy
    // opening and never offered again — exactly the RR4 defect.
    // ── r24.8 (WO-99a): slot 63 was DOUBLE-BOOKED, and wiring made it live ───
    // This restore has carried [63] since r24.6 (WO-36) — and so has the R18
    // row `ifthen_cue_note` (its ATHENA_R18_TAKE line). The collision was
    // harmless only because
    // WO-36's note had no consumer: nothing ever took it, so nothing ever
    // restored it, so the shared counter had exactly one live owner. WO-99
    // wired the note, which puts both owners on one budget: three ifthen
    // restores would silently exhaust the look note's three, and the reverse.
    // A note then dropped by the 640-byte cap would never be offered again —
    // the exact RR4 defect the C36 audit exists to prevent. Moved to its own
    // slot; `ifthen_cue_note` keeps [63], which it has always had alone in
    // practice. Found by the r24.8 merge's slot audit, not by a fixture:
    // nothing pins slot uniqueness, which is why it survived two rounds.
    void restore_look_taken_note() {
        if (!cfg_.enabled || !cfg_.look_taken_note) return;   // r24.8 (WO-99)
        std::lock_guard<std::mutex> lk(mu_);
        if (++note_retries_[aev::NS_look_taken_note] > 3) return;
        look_taken_note_ = true;
    }
    void restore_look_denied_note() {
        if (!cfg_.enabled) return;
        std::lock_guard<std::mutex> lk(mu_);
        if (++note_retries_[aev::NS_look_denied_note] > 3) return;
        look_denied_note_ = true;
    }
    void restore_look_change_note() {
        if (!cfg_.enabled) return;
        std::lock_guard<std::mutex> lk(mu_);
        if (++note_retries_[aev::NS_look_change_note] > 3) return;
        look_change_note_ = true;
        // r24.13 (WO-V2): look_change_band_/look_change_lit_ are deliberately
        // NOT reset by the take, so the retry renders the SAME sentence the
        // audit searched for. Nothing to restore here.
        // r24.14 (WO-R1): the same is true of look_change_shape_ /
        // look_change_where_ / look_local_dmean_ — held, never consumed.
        // r24.14 (fix 5, D-1): and now true without a caveat. Those three used
        // to be rewritten by EVERY look, so a look landing between the take and
        // this restore changed the sentence the retry rendered; they are
        // written only by a look that arms this latch, so the retry is exact.
        // The restore also re-arms the same guard note_look_taken reads: while
        // this note is owed, a localised look does not arm its own latch, so a
        // restored whole-frame claim cannot be displaced by a smaller one.
    }
    // r24.14 (WO-R2): the C36 row the seventh look latch is born with, in the
    // SAME edit as its take and its render site. Slot [82] — the slot the
    // declaration's own comment reserves BY NAME for this note; the array was
    // grown once, to [86], by the integrator, and nothing here touches it.
    // Capped at three retries, because an uncapped restore is the RR4 failure
    // the counter exists to stop.
    void restore_look_local_note() {
        if (!cfg_.enabled || !cfg_.look_regions || !cfg_.look_local_note) return;
        std::lock_guard<std::mutex> lk(mu_);
        // r24.14 (fix 4, the coherence pass): the snapshot check comes BEFORE
        // the retry counter, deliberately. A note superseded by a CHANGED look
        // did not fail to render — it was correctly withdrawn — so it must not
        // spend one of the three retries that exist to bound a note the byte
        // budget keeps dropping. See the paragraph below for what it guards.
        if (look_local_where_.empty()) return;
        if (++note_retries_[aev::NS_look_local_note] > 3) return;
        // r24.14 (review B§2): re-arming the latch is the whole restore, and it
        // is now ENOUGH. look_local_where_ / look_local_dmean_at_arm_ are the
        // arm-time snapshot and no take clears them, so the retry renders the
        // sentence the audit searched for even if a look landed in between —
        // which is what this row promised and, before the snapshot, could not
        // keep. A later CHANGED look clears the latch on purpose (a whole-frame
        // change supersedes the localised claim); the restore cannot resurrect
        // it, and must not — which is what the guard below is for.
        //
        // r24.14 (fix 4, the coherence pass): re-arm ONLY if the snapshot is
        // still there. field_of takes the note and then, at the end of the same
        // field, restores it if the byte budget dropped it; a CHANGED look
        // landing between those two points clears the latch and the snapshot,
        // and without this guard the restore would re-arm a latch whose take
        // can only return "". That is the WO-118b desync in miniature —
        // look_notes_armed() would tell the drain a note is pending while the
        // field gets nothing — and it is the same shape as the B§2 defect this
        // round just closed, so it is closed the same way. The invariant is now
        // TOTAL: look_local_note_ armed implies look_local_where_ non-empty,
        // and there is no path that breaks it.
        look_local_note_ = true;
    }
    // r24.13 (WO-P2): the C36 row the sixth latch is born with. Slot [81] —
    // the sixth new slot of the round, taken under the rule the array's own
    // comment states, and the array grew 81 -> 82 with it (see the declaration).
    void restore_recall_taken_note() {
        if (!cfg_.enabled || !cfg_.recall_budget_note) return;
        std::lock_guard<std::mutex> lk(mu_);
        if (++note_retries_[aev::NS_recall_taken_note] > 3) return;
        recall_taken_note_ = true;
    }
    void restore_keep_offer_note() {
        if (!cfg_.enabled) return;
        std::lock_guard<std::mutex> lk(mu_);
        if (++note_retries_[aev::NS_keep_offer_note] > 3) return;
        keep_offer_note_ = true;
    }
    void restore_look_grant_note(const std::string &s) {
        if (!cfg_.enabled || s.empty()) return;
        std::lock_guard<std::mutex> lk(mu_);
        if (++note_retries_[aev::NS_look_grant_note] > 3) return;
        // Re-derive the scope from the text the take_ built: only the away grant
        // says "even while <he> is away".
        // r24.6 (WO-52 / review #7): the SAME pronoun the note was built with.
        // take_look_grant_note renders "even while " + cfg_.pron_subj + " is
        // away", so the hard-coded "he" here silently downgraded an away grant
        // (2) to a present-only grant (1) under ATHENA_PERSON_PRONOUNS — a
        // consent scope narrowing with no log line. One accessor, both sites.
        if (look_grant_note_ == 0)
            look_grant_note_ = (s.find("even while " + cfg_.pron_subj + " is away")
                                    != std::string::npos) ? 2 : 1;
    }

