    std::string ifthen_cue_owner_, ifthen_cue_snapshot_; // r24.18: exact source through C36
    std::vector<std::string> expired_ifthen_steps_;     // r24.18: load-order handoff, cap three
    std::string ifthen_feedback_plan_;          // r24.18: the most recent received plan response
