    int         sweep_stage_ = 0;               // §1.4 two-alternative VTE sweep
    std::string sweep_topic_;
    double      last_reg_note_arm_t_ = -1e9;    // §3.5 reappraisal-note refractory
    std::string drift_catch_note_;              // §1.7c self-caught drift, lagged
    double      last_drift_catch_t_ = -1e9;
    double recent_absence_wall_s_ = 0.0;   // r21-full.14 (A5): last real absence
    double recent_absence_felt_s_ = 0.0;   //   …and how it ran from the inside
    double recent_absence_t_      = -1e9;  //   …and when it ended
    std::vector<std::string> tonight_dreams_;   // r21-full.14 (A1): landed this session
    std::vector<std::string> past_dreams_;      // r21-full.14 (A1): fed from dreams.tsv at startup
    // r21-full.11 (T4)
    std::string fok_note_;
    double      last_fok_t_ = -1e9;
    // r21-full.12 (U5)
